CURVE = ((0.05, 0.72), (0.25, 0.88), (0.5, 0.92), (1.0, 0.94), (2.0, 0.91))


def efficiency_at(load_a, table):
    if load_a <= table[0][0]:
        return table[0][1]
    if load_a >= table[-1][0]:
        return table[-1][1]
    for i in range(1, len(table)):
        x1, y1 = table[i]
        if load_a <= x1:
            x0, y0 = table[i - 1]
            t = (load_a - x0) / (x1 - x0)
            return y0 + t * (y1 - y0)
    return table[-1][1]


for load_a in (0.02, 0.1, 0.7, 1.5, 3.0):
    print(load_a, "A ->", round(efficiency_at(load_a, CURVE), 4))

